//! A tiny, self-contained PNG *encoder* used to manufacture identical input
//! byte streams for both libraries.  It deliberately does not use zlib: IDAT
//! data is emitted as zlib "stored" (uncompressed) deflate blocks, so the
//! generated bytes depend on nothing but this file.

pub const SIG: [u8; 8] = [0x89, b'P', b'N', b'G', 0x0d, 0x0a, 0x1a, 0x0a];

/* ------------------------------- crc32 ------------------------------- */

fn crc_table() -> [u32; 256] {
    let mut t = [0u32; 256];
    let mut n = 0usize;
    while n < 256 {
        let mut c = n as u32;
        let mut k = 0;
        while k < 8 {
            c = if c & 1 != 0 { 0xedb88320 ^ (c >> 1) } else { c >> 1 };
            k += 1;
        }
        t[n] = c;
        n += 1;
    }
    t
}

pub fn crc32(data: &[u8]) -> u32 {
    let t = crc_table();
    let mut c: u32 = 0xffff_ffff;
    for &b in data {
        c = t[((c ^ b as u32) & 0xff) as usize] ^ (c >> 8);
    }
    c ^ 0xffff_ffff
}

pub fn adler32(data: &[u8]) -> u32 {
    let mut a: u32 = 1;
    let mut b: u32 = 0;
    for &x in data {
        a = (a + x as u32) % 65521;
        b = (b + a) % 65521;
    }
    (b << 16) | a
}

/* ---------------------------- zlib stored ---------------------------- */

/// zlib stream containing `data` in uncompressed deflate blocks.
pub fn zlib_stored(data: &[u8]) -> Vec<u8> {
    let mut out = vec![0x78, 0x01];
    if data.is_empty() {
        out.extend_from_slice(&[0x01, 0x00, 0x00, 0xff, 0xff]);
    } else {
        let mut i = 0;
        while i < data.len() {
            let n = (data.len() - i).min(65535);
            let last = i + n >= data.len();
            out.push(if last { 1 } else { 0 });
            out.extend_from_slice(&(n as u16).to_le_bytes());
            out.extend_from_slice(&(!(n as u16)).to_le_bytes());
            out.extend_from_slice(&data[i..i + n]);
            i += n;
        }
    }
    out.extend_from_slice(&adler32(data).to_be_bytes());
    out
}

/* ------------------------------- chunks ------------------------------ */

pub fn chunk(name: &[u8; 4], data: &[u8]) -> Vec<u8> {
    let mut v = Vec::with_capacity(data.len() + 12);
    v.extend_from_slice(&(data.len() as u32).to_be_bytes());
    v.extend_from_slice(name);
    v.extend_from_slice(data);
    let mut crcbuf = Vec::with_capacity(4 + data.len());
    crcbuf.extend_from_slice(name);
    crcbuf.extend_from_slice(data);
    v.extend_from_slice(&crc32(&crcbuf).to_be_bytes());
    v
}

/// Same as `chunk` but with a deliberately wrong CRC.
pub fn chunk_bad_crc(name: &[u8; 4], data: &[u8]) -> Vec<u8> {
    let mut v = chunk(name, data);
    let n = v.len();
    v[n - 1] ^= 0xff;
    v
}

/// Chunk with an arbitrary declared length (used to build malformed streams).
pub fn chunk_len(name: &[u8; 4], declared_len: u32, data: &[u8]) -> Vec<u8> {
    let mut v = Vec::new();
    v.extend_from_slice(&declared_len.to_be_bytes());
    v.extend_from_slice(name);
    v.extend_from_slice(data);
    let mut crcbuf = Vec::new();
    crcbuf.extend_from_slice(name);
    crcbuf.extend_from_slice(data);
    v.extend_from_slice(&crc32(&crcbuf).to_be_bytes());
    v
}

pub fn ihdr(w: u32, h: u32, bd: u8, ct: u8, comp: u8, filt: u8, il: u8) -> Vec<u8> {
    let mut d = Vec::new();
    d.extend_from_slice(&w.to_be_bytes());
    d.extend_from_slice(&h.to_be_bytes());
    d.push(bd);
    d.push(ct);
    d.push(comp);
    d.push(filt);
    d.push(il);
    chunk(b"IHDR", &d)
}

/* ---------------------------- raw image data ------------------------- */

pub fn channels(ct: u8) -> u32 {
    match ct {
        0 => 1,
        2 => 3,
        3 => 1,
        4 => 2,
        6 => 4,
        _ => 1,
    }
}

pub fn rowbytes(width: u32, bd: u8, ct: u8) -> usize {
    let bits = width as u64 * channels(ct) as u64 * bd as u64;
    ((bits + 7) / 8) as usize
}

/* Adam7 */
const START_ROW: [u32; 7] = [0, 0, 4, 0, 2, 0, 1];
const START_COL: [u32; 7] = [0, 4, 0, 2, 0, 1, 0];
const ROW_INC: [u32; 7] = [8, 8, 8, 4, 4, 2, 2];
const COL_INC: [u32; 7] = [8, 8, 4, 4, 2, 2, 1];

pub fn pass_rows(h: u32, pass: usize) -> u32 {
    if h <= START_ROW[pass] {
        0
    } else {
        (h - START_ROW[pass] + ROW_INC[pass] - 1) / ROW_INC[pass]
    }
}

pub fn pass_cols(w: u32, pass: usize) -> u32 {
    if w <= START_COL[pass] {
        0
    } else {
        (w - START_COL[pass] + COL_INC[pass] - 1) / COL_INC[pass]
    }
}

/// Build the *filtered* (filter byte 0 prefixed) raw stream for a
/// non-interlaced image whose rows are supplied verbatim.
pub fn filtered_none(rows: &[Vec<u8>]) -> Vec<u8> {
    let mut v = Vec::new();
    for r in rows {
        v.push(0u8);
        v.extend_from_slice(r);
    }
    v
}

/// Build the filtered raw stream for an Adam7-interlaced image.  `pixel_at` is
/// asked for the bytes of each sub-image row.
pub fn filtered_adam7(
    w: u32,
    h: u32,
    bd: u8,
    ct: u8,
    get: &mut dyn FnMut(usize, u32, u32) -> Vec<u8>,
) -> Vec<u8> {
    let mut v = Vec::new();
    for pass in 0..7 {
        let pr = pass_rows(h, pass);
        let pc = pass_cols(w, pass);
        if pr == 0 || pc == 0 {
            continue;
        }
        let rb = rowbytes(pc, bd, ct);
        for r in 0..pr {
            v.push(0u8);
            let mut row = get(pass, r, pc);
            row.resize(rb, 0);
            v.extend_from_slice(&row);
        }
    }
    v
}

/* ------------------------------ assembling --------------------------- */

pub struct PngBuilder {
    pub out: Vec<u8>,
}

impl PngBuilder {
    pub fn new() -> PngBuilder {
        PngBuilder { out: SIG.to_vec() }
    }
    pub fn raw(&mut self, bytes: &[u8]) -> &mut Self {
        self.out.extend_from_slice(bytes);
        self
    }
    pub fn chunk(&mut self, name: &[u8; 4], data: &[u8]) -> &mut Self {
        let c = chunk(name, data);
        self.out.extend_from_slice(&c);
        self
    }
    pub fn ihdr(&mut self, w: u32, h: u32, bd: u8, ct: u8, il: u8) -> &mut Self {
        let c = ihdr(w, h, bd, ct, 0, 0, il);
        self.out.extend_from_slice(&c);
        self
    }
    /// Split `raw` (already filtered) into IDAT chunks of at most `split` bytes
    /// of zlib stream each.
    pub fn idat(&mut self, raw: &[u8], split: usize) -> &mut Self {
        let z = zlib_stored(raw);
        let split = if split == 0 { z.len().max(1) } else { split };
        let mut i = 0;
        while i < z.len() {
            let n = (z.len() - i).min(split);
            let c = chunk(b"IDAT", &z[i..i + n]);
            self.out.extend_from_slice(&c);
            i += n;
        }
        self
    }
    pub fn iend(&mut self) -> Vec<u8> {
        let c = chunk(b"IEND", &[]);
        self.out.extend_from_slice(&c);
        std::mem::take(&mut self.out)
    }
}
